// Argument actions. Only the two kinds this CLI needs exist: `store` (the
// default for `add_argument`) and `help` (the automatic `-h/--help`).

export const STORE = 'store';
export const HELP = 'help';

/**
 * `nargs === 0` marks a flag that consumes no value; `nargs === null` marks
 * argparse's default "exactly one value".
 */
export class Action {
  constructor({
    optionStrings,
    dest,
    kind = STORE,
    nargs = null,
    required = false,
    metavar = null,
    help = '',
    type = null,
  }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.kind = kind;
    this.nargs = nargs;
    this.required = required;
    this.help = help;
    this.type = type;
    // argparse derives an absent metavar for an optional from `dest.upper()`.
    this.metavar = metavar === null ? dest.toUpperCase() : metavar;
  }
}

/** `--flag` -> dest `flag`; argparse also maps inner dashes to underscores. */
export function destFromOptionStrings(optionStrings) {
  const long = optionStrings.find((option) => option.startsWith('--'));
  const chosen = long === undefined ? optionStrings[0] : long;
  return chosen.replace(/^-+/, '').replace(/-/g, '_');
}

export function makeHelpAction() {
  return new Action({
    optionStrings: ['-h', '--help'],
    dest: 'help',
    kind: HELP,
    nargs: 0,
    help: 'show this help message and exit',
  });
}
