1	// Differential runner: replays a corpus of argv arrays against both the Python
2	// executable and the Node port and reports byte-level divergences.
3	// Usage: node diff.mjs corpus.json [maxExamples] [concurrency]
4	import { spawn } from 'node:child_process';
5	import { readFileSync } from 'node:fs';
6	
7	const EXE = '/workspace/dataset/test12_executable';
8	const NODE_ENTRY = '/output/test12.mjs';
9	
10	// The two programs legitimately report different prog names in usage/error text
11	// (basename of argv[0], exactly as Python does), so normalise that one token.
12	const normalise = (text) =>
13	  text.split('test12_executable').join('%PROG%').split('test12.mjs').join('%PROG%');
14	
15	function run(cmd, argv) {
16	  return new Promise((resolve) => {
17	    const child = spawn(cmd[0], [...cmd.slice(1), ...argv], { stdio: ['ignore', 'pipe', 'pipe'] });
18	    let out = '';
19	    let err = '';
20	    child.stdout.setEncoding('utf8');
21	    child.stderr.setEncoding('utf8');
22	    child.stdout.on('data', (chunk) => { out += chunk; });
23	    child.stderr.on('data', (chunk) => { err += chunk; });
24	    child.on('error', (error) => resolve({ out, err: `${err}<spawn error: ${error.message}>`, code: -1 }));
25	    child.on('close', (code) => resolve({ out, err, code }));
26	  });
27	}
28	
29	const corpus = JSON.parse(readFileSync(process.argv[2], 'utf8'));
30	const maxExamples = Number(process.argv[3] ?? 8);
31	const concurrency = Number(process.argv[4] ?? 16);
32	const mismatches = [];
33	
34	let next = 0;
35	async function worker() {
36	  for (;;) {
37	    const index = next;
38	    next += 1;
39	    if (index >= corpus.length) return;
40	    const argv = corpus[index];
41	    const [expected, actual] = await Promise.all([run([EXE], argv), run(['node', NODE_ENTRY], argv)]);
42	    const same =
43	      normalise(expected.out) === normalise(actual.out) &&
44	      normalise(expected.err) === normalise(actual.err) &&
45	      expected.code === actual.code;
46	    if (!same) mismatches.push({ index, argv, expected, actual });
47	  }
48	}
49	
50	await Promise.all(Array.from({ length: concurrency }, worker));
51	mismatches.sort((left, right) => left.index - right.index);
52	
53	console.log(`total=${corpus.length} mismatches=${mismatches.length}`);
54	for (const m of mismatches.slice(0, maxExamples)) {
55	  console.log(JSON.stringify(m));
