// How discriminating is the corpus? Counts reference outcomes so a "0 mismatches"
// result cannot be explained by every case producing the empty string.
import { spawn } from 'node:child_process';
import { readFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test12_executable';
const corpus = JSON.parse(readFileSync('/tmp/corpus/hrp-lengths.json', 'utf8'));

function run(argv) {
  return new Promise((resolve) => {
    const child = spawn(EXE, argv, { stdio: ['ignore', 'pipe', 'pipe'] });
    let out = '';
    let err = '';
    child.stdout.setEncoding('utf8');
    child.stderr.setEncoding('utf8');
    child.stdout.on('data', (c) => { out += c; });
    child.stderr.on('data', (c) => { err += c; });
    child.on('close', (code) => resolve({ out, err, code }));
  });
}

const tally = { printedList: 0, printedNone: 0, empty: 0, stderr: 0 };
let next = 0;
async function worker() {
  for (;;) {
    const i = next; next += 1;
    if (i >= corpus.length) return;
    const r = await run(corpus[i]);
    if (r.err !== '' || r.code !== 0) tally.stderr += 1;
    else if (r.out === '') tally.empty += 1;
    else if (r.out.includes('None')) tally.printedNone += 1;
    else tally.printedList += 1;
  }
}
await Promise.all(Array.from({ length: 24 }, worker));
console.log(JSON.stringify(tally), 'total', corpus.length);

